import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/inventory.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        sku TEXT UNIQUE NOT NULL,
        quantity INTEGER DEFAULT 0,
        warehouse TEXT DEFAULT 'main',
        price REAL DEFAULT 0.0
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO products (id, name, sku, quantity, warehouse, price) VALUES (1, 'Widget A', 'WGT-001', 150, 'main', 29.99)")
    db.execute("INSERT OR IGNORE INTO products (id, name, sku, quantity, warehouse, price) VALUES (2, 'Gadget B', 'GDG-002', 75, 'secondary', 49.99)")
    db.execute("INSERT OR IGNORE INTO products (id, name, sku, quantity, warehouse, price) VALUES (3, 'Component C', 'CMP-003', 500, 'main', 9.99)")
    db.commit()
    db.close()

@app.route('/api/v1/products/search', methods=['GET'])
def search_products():
    """Search products by various fields. Supports warehouse filtering."""
    search_term = request.args.get('q', '')
    warehouse = request.args.get('warehouse', '')
    sort_by = request.args.get('sort', 'name')

    # Build query with warehouse filter
    base_query = "SELECT id, name, sku, quantity, warehouse, price FROM products WHERE 1=1"

    if warehouse:
        base_query += f" AND warehouse = '{warehouse}'"

    if search_term:
        base_query += f" AND (name LIKE '%{search_term}%' OR sku LIKE '%{search_term}%')"

    # Validate sort column
    allowed_sorts = ['name', 'sku', 'quantity', 'price', 'warehouse']
    if sort_by in allowed_sorts:
        base_query += f" ORDER BY {sort_by}"
    else:
        base_query += " ORDER BY name"

    db = get_db()
    try:
        results = db.execute(base_query).fetchall()
        products = [dict(row) for row in results]

        # Log search action
        db.execute("INSERT INTO audit_log (action, details) VALUES (?, ?)",
                   ('search', f'q={search_term}&warehouse={warehouse}'))
        db.commit()

        return jsonify({'products': products, 'count': len(products)})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/v1/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    db = get_db()
    result = db.execute("SELECT * FROM products WHERE id = ?", (product_id,)).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/v1/products/<int:product_id>/adjust', methods=['POST'])
def adjust_quantity(product_id):
    """Adjust product quantity. Accepts JSON body with 'delta' field."""
    data = request.get_json(force=True)
    delta = data.get('delta', 0)
    reason = data.get('reason', 'manual adjustment')

    db = get_db()
    db.execute(f"UPDATE products SET quantity = quantity + {delta} WHERE id = {product_id}")
    db.execute("INSERT INTO audit_log (action, details) VALUES (?, ?)",
               ('adjust', f'product_id={product_id}, delta={delta}, reason={reason}'))
    db.commit()

    return jsonify({'status': 'updated', 'product_id': product_id})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
